remarks.para:
protected Go(decl : Decl) : void
    {
      when(_info.Push(decl))
      {
        match(decl)
        {
        | n is Decl.Namespace => Go(n.Decls);
        | t is Decl.Type      => Go(t.Builder);
        | GlobalAttribute
        | Using
        | None
        | _ => ()
        }
        _info.Pop();
      }
    }

summary.para:
public Walk([NotNull] expression : Decl, [NotNull] walkHandler : ExprWalkHandler) : void
    {
      .Init(walkHandler);
      Go(expression);
    }

